// JS 版参考实现
async function executeToolCalls(calls, registry, { maxConc = 5, maxChars = 8000 } = {}) {
  const limiter = createLimiter(maxConc) // p-limit 风格信号量
  const results = await Promise.all(calls.map((call) => limiter(async () => {
    const base = { role: 'tool', tool_call_id: call.id }
    try {
      const fn = registry[call.function.name]
      if (!fn) throw Object.assign(new Error('unknown tool'), { code: 'TOOL_NOT_FOUND' })
      let args
      try { args = JSON.parse(call.function.arguments || '{}') }
      catch (e) { throw Object.assign(new Error('bad arguments json'), { code: 'ARGS_PARSE_FAIL' }) }
      let out = await fn(args)
      let text = typeof out === 'string' ? out : JSON.stringify(out)
      if (text.length > maxChars) // 截断保头部+marker，尾部信息通常低价值
        text = text.slice(0, maxChars) + `\n[truncated ${text.length - maxChars} chars]`
      return { ...base, content: text }
    } catch (err) {
      // 失败也要回信：漏掉 id 会让下一轮请求被 API 拒绝
      return { ...base, content: JSON.stringify({
        error_code: err.code ?? 'TOOL_RUNTIME_ERROR',
        message: String(err.message).slice(0, 500),
        retryable: err.code !== 'TOOL_NOT_FOUND' && err.code !== 'ARGS_PARSE_FAIL',
      }) }
    }
  })))
  return results // Promise.all 保持与 calls 同序
}
